<div class="topbar"><div><h1>Growth &amp; reports</h1><p class="muted" style="margin:4px 0 0">Opportunities researched by agents, ranked and evidence-labelled. Daily and weekly reports are emailed to you automatically.</p></div></div>
<form class="panel row" method="post" action="/admin/growth/research"><?= App\Csrf::field() ?><input name="focus" type="text" placeholder="Optional focus, e.g. trades businesses in Moncton, recurring revenue" style="flex:1"><button class="btn btn-primary btn-sm">Find three new opportunities</button></form>
<div class="grid g2" style="align-items:start"><div class="panel"><h2>Opportunities</h2><?php if (!$opps): ?><div class="empty">No opportunities yet. Ask the Research agent above.</div><?php endif; ?>
<?php foreach ($opps as $o): ?><details class="card flat" style="margin-bottom:10px"><summary><b><?= e($o['name']) ?></b> <span class="badge">score <?= (int)$o['score'] ?></span> <span class="badge <?= $o['confidence'] === 'high' ? 'b-green' : ($o['confidence'] === 'medium' ? 'b-blue' : 'b-amber') ?>">confidence <?= e($o['confidence']) ?></span></summary>
  <div class="small" style="margin-top:8px"><p><b>Audience:</b> <?= e($o['audience']) ?></p><p><b>Problem:</b> <?= e($o['problem']) ?></p><p><b>Evidence:</b> <?= e($o['evidence']) ?></p><p><b>Monetization:</b> <?= e($o['monetization']) ?></p><p><b>Risks:</b> <?= e($o['risks']) ?></p><p><b>Recommendation:</b> <?= e($o['recommendation']) ?></p>
  <?php $src = jdec($o['sources']); if ($src): ?><p><b>Sources:</b> <?= e(implode(' · ', $src)) ?></p><?php else: ?><p class="muted">No sources cited, so treat this as an assumption.</p><?php endif; ?></div></details><?php endforeach; ?></div>
<div class="panel"><h2>Reports sent</h2><?php if (!$reports): ?><p class="small muted">The first daily report is sent after 12:00 UTC (about 8–9am Atlantic) once cron is running.</p><?php endif; ?><?php foreach ($reports as $r): ?><div class="small"><?= e($r['created_at']) ?> · <?= e($r['subject']) ?> · <?= e($r['status']) ?></div><?php endforeach; ?>
  <h2 style="margin-top:14px">Today's snapshot</h2><pre style="background:var(--surface);color:var(--ink)"><?= e(App\Metrics::dailyReport()) ?></pre></div></div>
